    #   0005: STORE r1    (fall-through from BEQ)
    #   0007: JMP 0009    (skip to end -- note: this is 3 bytes, target 0x0009)
    #   0009: RET         (branch target and jump target merge here)
    #
    # Note: BEQ target 0x0006 is actually a STORE at 0x0005?
