    program = bytes([
        0x02, 0x00,             # 0000: LOAD r0
        0x06, 0x07, 0x00,       # 0002: BEQ 0007
        0x03, 0x01,             # 0005: STORE r1
        0x08,                   # 0007: RET
    ])

    cfg = build_cfg(program, entry_point=0)
    if cfg is None:
        print("build_cfg() returned None -- implement the TODO sections.")
